import{_ as t,o as r,c as a,a2 as i}from"./chunks/framework.Dkj3JE0_.js";const h=JSON.parse('{"title":"Plan JLPT N2","description":"","frontmatter":{"title":"Plan JLPT N2"},"headers":[],"relativePath":"fr/blogs/JLPT-N2/plan.md","filePath":"fr/blogs/JLPT-N2/plan.md"}'),s={name:"fr/blogs/JLPT-N2/plan.md"};function n(o,e,l,d,u,c){return r(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="plan-d-apprentissage-jlpt-n2" tabindex="-1">Plan d’apprentissage JLPT N2 <a class="header-anchor" href="#plan-d-apprentissage-jlpt-n2" aria-label="Permalink to &quot;Plan d’apprentissage JLPT N2&quot;">​</a></h1><blockquote><p><strong>Hypothèse de travail :</strong> examen le <strong>dimanche 6 décembre 2026</strong>. Couverture intensive du <strong>13 octobre → vendredi 14 novembre</strong> (clôture souple le <strong>16 novembre</strong>) avec un plafond strict de <strong>2,0 heures par jour</strong> (~<strong>14 heures par semaine</strong>). Le <strong>1er–5 décembre</strong> sert uniquement de marge (≤1 heure de révision) ; <strong>aucun nouveau premier passage</strong> en décembre. Ne pas monter en charge en décembre.</p></blockquote><h2 id="criteres-d-achevement" tabindex="-1">Critères d’achèvement <a class="header-anchor" href="#criteres-d-achevement" aria-label="Permalink to &quot;Critères d’achèvement&quot;">​</a></h2><ul><li>Vider la file de vocabulaire restante (~<strong>2000</strong> mots à ~<strong>60 par jour</strong>) et les leçons vidéo restantes (~<strong>180</strong> à ~<strong>5–6 par jour</strong>) d’ici la mi-novembre.</li><li>Tenir à jour notes de grammaire, phrases d’exemple et cartes tirées des erreurs avec l’aide de Caligo — reconnaître en contexte, pas seulement réviser des cartes.</li><li>Faire tourner la pratique du soir entre grammaire, entraînement à l’examen, lecture et écoute, pour qu’aucune compétence ne reste de côté une semaine entière.</li><li>Entrer en décembre avec le premier passage terminé ; n’utiliser le 1er–5 déc. que pour une révision légère et la logistique avant l’examen du 6 décembre.</li></ul><h2 id="priorites-actuelles-au-14-oct-2026" tabindex="-1">Priorités actuelles (au 14 oct. 2026) <a class="header-anchor" href="#priorites-actuelles-au-14-oct-2026" aria-label="Permalink to &quot;Priorités actuelles (au 14 oct. 2026)&quot;">​</a></h2><p><strong>Aujourd’hui :</strong> session de vocabulaire sur l’appli dans le créneau du matin.</p><p><strong>Pistes en cours</strong></p><table tabindex="0"><thead><tr><th>Piste</th><th style="text-align:right;">Reste (env.)</th><th style="text-align:right;">Rythme quotidien</th></tr></thead><tbody><tr><td>Vocabulaire (appli)</td><td style="text-align:right;">~2000</td><td style="text-align:right;">~60 / jour</td></tr><tr><td>Leçons vidéo</td><td style="text-align:right;">~180</td><td style="text-align:right;">~5–6 / jour</td></tr><tr><td>Grammaire / notes / cartes</td><td style="text-align:right;">En continu avec Caligo</td><td style="text-align:right;">lun. et mer. soir</td></tr><tr><td>Pratique / lecture / écoute</td><td style="text-align:right;">En rotation le soir</td><td style="text-align:right;">Voir le rythme ci-dessous</td></tr></tbody></table><p>Le travail approfondi de grammaire et de vidéo avec Caligo vient une fois le bloc de vocabulaire du jour terminé — appuyer sur Caligo pour lancer ces parties ; ne pas s’inventer une soirée plus chargée.</p><h2 id="rythme-quotidien-plafond-2-0-h" tabindex="-1">Rythme quotidien (plafond 2,0 h) <a class="header-anchor" href="#rythme-quotidien-plafond-2-0-h" aria-label="Permalink to &quot;Rythme quotidien (plafond 2,0 h)&quot;">​</a></h2><p>Les créneaux ne doivent pas chevaucher le CFA (20:00–02:00), le sport (18:00–20:00) ni le rapport hebdomadaire du lundi (08:00–10:00).</p><table tabindex="0"><thead><tr><th>Créneau</th><th style="text-align:right;">Horaire</th><th>Travail</th></tr></thead><tbody><tr><td>Vocabulaire du matin</td><td style="text-align:right;">06:45–07:15</td><td>Vocabulaire sur l’appli (~60 mots).</td></tr><tr><td>Vidéo du matin</td><td style="text-align:right;">07:15–08:05</td><td>Leçons vidéo (~5–6).</td></tr><tr><td>Rotation du soir</td><td style="text-align:right;">21:00–21:40</td><td>Compétence du jour (tableau ci-dessous).</td></tr></tbody></table><h3 id="rotation-du-soir-21-00–21-40" tabindex="-1">Rotation du soir (21:00–21:40) <a class="header-anchor" href="#rotation-du-soir-21-00–21-40" aria-label="Permalink to &quot;Rotation du soir (21:00–21:40)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jour</th><th>Priorité</th></tr></thead><tbody><tr><td>lun.</td><td>Grammaire · notes / cartes (Caligo)</td></tr><tr><td>mar.</td><td>Pratique (séries au format de l’examen)</td></tr><tr><td>mer.</td><td>Grammaire · notes / cartes (Caligo)</td></tr><tr><td>jeu.</td><td>Lecture</td></tr><tr><td>ven.</td><td>Écoute</td></tr><tr><td>sam.</td><td>Pratique (séries au format de l’examen)</td></tr><tr><td>dim.</td><td>Écoute</td></tr></tbody></table><h2 id="feuille-de-route-intensive" tabindex="-1">Feuille de route intensive <a class="header-anchor" href="#feuille-de-route-intensive" aria-label="Permalink to &quot;Feuille de route intensive&quot;">​</a></h2><h3 id="phase-a-—-couverture-13-oct-→-ven-14-nov" tabindex="-1">Phase A — Couverture (13 oct. → ven. 14 nov.) <a class="header-anchor" href="#phase-a-—-couverture-13-oct-→-ven-14-nov" aria-label="Permalink to &quot;Phase A — Couverture (13 oct. → ven. 14 nov.)&quot;">​</a></h3><ul><li>Tenir le plafond de <strong>2,0 h/jour</strong> ; le temps manqué le matin ne déborde pas sur le bloc CFA du soir.</li><li>Vocabulaire et vidéo tous les jours au rythme ci-dessus jusqu’à vider les files.</li><li>Soirs de grammaire : comparer les structures proches, phrases d’exemple courtes, cartes tirées des erreurs — pas un deuxième manuel.</li><li>Soirs de pratique / lecture / écoute : travail chronométré ou en un seul passage ; noter les erreurs pour la prochaine séance de grammaire ou de cartes.</li></ul><p><strong>Clôture souple : 16 novembre</strong> — terminer le premier passage restant ; ensuite, ne plus ouvrir de nouveaux chapitres de grammaire ni de nouvelles séries vidéo.</p><h3 id="phase-b-—-marge-1er–5-dec" tabindex="-1">Phase B — Marge (1er–5 déc.) <a class="header-anchor" href="#phase-b-—-marge-1er–5-dec" aria-label="Permalink to &quot;Phase B — Marge (1er–5 déc.)&quot;">​</a></h3><ul><li>Révision uniquement, <strong>≤1 heure par jour</strong>.</li><li>Paires de grammaire les plus confondues, indices d’écoute faibles et erreurs de vocabulaire récurrentes.</li><li>Vérifier la logistique de l’examen ; protéger le sommeil.</li><li><strong>Aucun nouveau contenu de premier passage.</strong></li></ul><h3 id="jour-de-l-examen-—-dim-6-dec" tabindex="-1">Jour de l’examen — dim. 6 déc. <a class="header-anchor" href="#jour-de-l-examen-—-dim-6-dec" aria-label="Permalink to &quot;Jour de l’examen — dim. 6 déc.&quot;">​</a></h3><ul><li>Un léger échauffement seulement s’il est utile ; pas de bachotage.</li></ul><h2 id="bilan-hebdomadaire-note-facultative-du-dimanche" tabindex="-1">Bilan hebdomadaire (note facultative du dimanche) <a class="header-anchor" href="#bilan-hebdomadaire-note-facultative-du-dimanche" aria-label="Permalink to &quot;Bilan hebdomadaire (note facultative du dimanche)&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes min-light min-dark vp-code" tabindex="0"><code><span class="line"><span>Vocabulaire fait / restant :</span></span>
<span class="line"><span>Vidéos faites / restantes :</span></span>
<span class="line"><span>Créneaux du soir tenus (grammaire / pratique / lecture / écoute) :</span></span>
<span class="line"><span>Une structure ou un passage encore fragile :</span></span>
<span class="line"><span>Ajuster le rythme la semaine prochaine ? (rester au plafond — ne pas ajouter d’heures)</span></span></code></pre></div><h2 id="les-sept-prochains-jours-14–20-oct" tabindex="-1">Les sept prochains jours (14–20 oct.) <a class="header-anchor" href="#les-sept-prochains-jours-14–20-oct" aria-label="Permalink to &quot;Les sept prochains jours (14–20 oct.)&quot;">​</a></h2><ul><li>[ ] Garder chaque jour le vocabulaire du matin (06:45–07:15) et la vidéo (07:15–08:05).</li><li>[ ] Lun. 14 / mer. 16 soir : grammaire avec Caligo une fois sollicité — notes et cartes d’exemples, pas une séance plus longue.</li><li>[ ] Mar. 15 / sam. 18 soir : séries d’exercices ; noter les erreurs.</li><li>[ ] Jeu. 17 soir : lecture ; ven. 18 / dim. 20 soir : écoute.</li><li>[ ] Rester sous le plafond de 2,0 h/jour ; ne pas empiéter sur le bloc CFA de nuit.</li><li>[ ] Ne pas prévoir de rush de premier passage en décembre.</li></ul>`,26)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
